// Prepare a stable, NUL-terminated input as required
auto s = FUZZ_PARAM_STR();
size_t inlen = s.size();
if (inlen > 1024) inlen = 1024;  // keep allocations small
char *cbuf = (char *) mg_calloc(inlen + 1, 1);
if (!cbuf) { FUZZ_BAIL(); }
memcpy(cbuf, s.c_str(), inlen);
cbuf[inlen] = '\0';
// Call target constructor; it does not allocate, it points to provided buffer
struct mg_str tmp = mg_str(cbuf);
// Persist the result as an object for the pool
struct mg_str *mgstr = (struct mg_str *) mg_calloc(1, sizeof(*mgstr));
if (!mgstr) { mg_free(cbuf); FUZZ_BAIL(); }
*mgstr = tmp;
// Track ownership of the backing buffer for later cleanup
FUZZ_SET_ATTR_INT(mgstr, "owns_buf", 1);
FUZZ_SET_ATTR_PTR(mgstr, "buf_ptr", (void *) cbuf);
// Validation: input is NUL-terminated, output buf matches our allocated buffer
// End stub

