// Allocate queue object and backing ring buffer
size_t cap = (size_t) ((*FUZZ_PARAM(unsigned int) % 481) + 32);  // [32, 512]
char *buf = (char *) mg_calloc(cap, 1);
struct mg_queue *q = (struct mg_queue *) mg_calloc(1, sizeof(*q));
if (!buf || !q) { if (buf) mg_free(buf); if (q) mg_free(q); FUZZ_BAIL(); }
mg_queue_init(q, buf, cap);
// Track ownership of buffer for later lifecycle functions
FUZZ_SET_ATTR_PTR(q, "buf", (void *) buf);
FUZZ_SET_ATTR_INT(q, "cap", (int) cap);
FUZZ_SET_ATTR_INT(q, "last_booked", 0);
FUZZ_SET_ATTR_INT(q, "last_next", 0);
// Validation: queue pointer non-NULL; writable buffer provided
// End stub

// Must follow a successful mg_queue_book; read the reserved size
int last = FUZZ_GET_ATTR_INT(q, "last_booked");
if (last <= 0) { FUZZ_BAIL(); }
// Commit a size less than or equal to reserved
size_t commit = (size_t) (1 + (*FUZZ_PARAM(unsigned int) % (unsigned) last));
mg_queue_add(q, commit);
// Reduce remaining reservation; if zero, clear attribute
int remain = last - (int) commit;
FUZZ_SET_ATTR_INT(q, "last_booked", remain > 0 ? remain : 0);
// Validation: single-producer semantics respected; commit <= reserved
// End stub

// Obtain the oldest message without removing it
char *rptr = NULL;
size_t sz = mg_queue_next(q, &rptr);
// Track size to be used by mg_queue_del
FUZZ_SET_ATTR_INT(q, "last_next", (int) sz);
// Validation: output pointer argument was non-NULL; size recorded for deletion
// End stub

// Must match the size returned by the last mg_queue_next
int last = FUZZ_GET_ATTR_INT(q, "last_next");
if (last <= 0) { FUZZ_BAIL(); }
mg_queue_del(q, (size_t) last);
FUZZ_SET_ATTR_INT(q, "last_next", 0);
// Validation: consumed exactly the last observed message size
// End stub

