import random
import string
from typing import List

# Data type: NUL-terminated string
# Target stubs use FUZZ_PARAM_STR() and FUZZ_PARAM_FILENAME().
# Provide interesting, valid C strings (ASCII/UTF-8) covering URLs, HTTP headers,
# JSON, credentials, hex/base64 payloads, Wi-Fi SSIDs/passwords, etc.
# The fuzzer runtime will map this single buffer to the various FUZZ_PARAM_* calls,
# so we concatenate multiple NUL-terminated strings and a couple of path-like names.

MAX_TOTAL = 4096

