    "http", "https", "ws", "wss", "mqtt", "mqtts", "tcp", "udp", "sntp"
]
HOSTS = [
    "example.com", "localhost", "[::1]", "127.0.0.1", "sub.domain.example"
]
URIS = ["/", "/index.html", "/api/v1", "/ws", "/data?x=1&y=two"]

HEX_SAMPLES = [
    "", "00", "deadBEEF", "0123456789abcdef", "CAFEBABE00FF"
]
B64_SAMPLES = [
    "", "TQ==", "SGVsbG8=", "AAEC/f8=", "eyJhIjoxfQ=="
]
HEADER_NAMES = [
    "Host", "User-Agent", "Content-Type", "Authorization", "Cookie", "X-Custom-Header"
]
JSON_SAMPLES = [
    "{}",
    '{"a":1}',
    '{"a": {"b": [1,2,3], "c": true}}',
    '{"id":1,"method":"add","params":[1,2]}',
    '{"token":"SGVsbG8=","hex":"deadbeef"}'
]

USERNAMES = ["user", "admin", "test", "alice", "bob"]
PASSWORDS = ["pass", "12345678", "Pa$$w0rd", "secret", "token-xyz"]
SSID_SAMPLES = ["HomeWiFi", "Office-2G", "Cafe_Free_WiFi", "实验室", "ネット"]
PASS_SAMPLES = ["password", "1234567890", "longerpasswithsymbols!@#", "пароль", "اختبار"]

FILENAME_SAMPLES = [
    "./test.txt", "/tmp/data.bin", "./dir/../dir/file.log", "C:/temp/out.txt", "./www/index.html"
]
DIR_SAMPLES = ["./", ".", "./static", "./var/www", "/tmp"]

COOKIE_SAMPLES = [
    "k=v; a=1; b=two", "session=abcd.efgh; Path=/; HttpOnly", "name=val"
]

# Helper generators

def rand_ascii(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    chars = string.ascii_letters + string.digits + " _-.:/[]?&=%@,+#\"'(){}"
    return "".join(rng.choice(chars) for _ in range(n))


def make_url(rng: random.Random) -> str:
    sch = rng.choice(SCHEMES)
    host = rng.choice(HOSTS)
    uri = rng.choice(URIS)
    # Optionally embed user:pass and port
    parts = []
    if rng.random() < 0.4:
        parts.append(rng.choice(USERNAMES))
        if rng.random() < 0.7:
            parts[-1] += ":" + rng.choice(PASSWORDS)
        parts[-1] += "@"
    hostport = host
    if rng.random() < 0.7:
        port = rng.choice([80, 443, 1883, 8883, 8000, 0, 65535])
        hostport += f":{port}"
    return f"{sch}://" + ("".join(parts)) + hostport + (uri if rng.random() < 0.9 else "")


def make_header_name(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rng.choice(HEADER_NAMES)
    # random token-ish header name
    base = rand_ascii(rng, 3, 16)
    return "-".join(filter(None, base.replace(" ", "-").split("-")))


def make_http_request(rng: random.Random) -> str:
    method = rng.choice(["GET", "POST", "PUT", "HEAD"])
    path = rng.choice(URIS)
    host = rng.choice(["example", "x", "test.local", "127.0.0.1"]) \
        + (":" + str(rng.choice([80, 8080, 1234])) if rng.random() < 0.5 else "")

    # One custom header of interest from fuzz string pool
    hn = make_header_name(rng)
    hv = rand_ascii(rng, 1, 16)
    body = ""
    if method in ("POST", "PUT") and rng.random() < 0.7:
        # form-ish
        kvs = [f"k{i}={rand_ascii(rng,1,6)}" for i in range(rng.randint(1,3))]
        body = "&".join(kvs)
    req = f"{method} {path} HTTP/1.1\r\nHost: {host}\r\n{hn}: {hv}\r\n"
    if body:
        req += f"Content-Length: {len(body)}\r\n\r\n{body}"
    else:
        req += "\r\n"
    return req


def make_json(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return rng.choice(JSON_SAMPLES)
    # build small object with varied types
    obj = {
        "n": rng.randint(-5, 1000),
        "b": rng.choice([True, False]),
        "s": rand_ascii(rng, 0, 16),
        "hex": rng.choice(HEX_SAMPLES),
        "b64": rng.choice(B64_SAMPLES),
        "arr": [rng.randint(0,9) for _ in range(rng.randint(0,4))],
    }
    # simple JSON encoder to avoid importing json for compactness (still stdlib, but keep predictable)
    import json as _json
    return _json.dumps(obj, ensure_ascii=False)


def make_cookie(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(COOKIE_SAMPLES)
    pairs = [f"{rand_ascii(rng,1,6)}={rand_ascii(rng,1,6)}" for _ in range(rng.randint(1,4))]
    return "; ".join(pairs)


def nul(s: str) -> bytes:
    # Ensure no embedded NULs; fuzz stubs assume C strings
    if "\x00" in s:
        s = s.replace("\x00", " ")
    return s.encode('utf-8', errors='ignore') + b"\x00"


def assemble_strings(rng: random.Random) -> bytes:
    parts: List[bytes] = []

    # 1) General-purpose short strings (used by many stubs)
    basics = [
        "", "a", "Hello", "World", "UPPERlower123", "with spaces", "symbols-_.:+/[]?&=%",
    ]
    for s in basics:
        parts.append(nul(s))

    # 2) URLs for mg_url_* and various connect/listen functions
    for _ in range(6):
        parts.append(nul(make_url(rng)))

    # 3) HTTP requests for parsing and header lookup
    for _ in range(3):
        parts.append(nul(make_http_request(rng)))

    # 4) Header names for mg_http_get_header
    for _ in range(4):
        parts.append(nul(make_header_name(rng)))

    # 5) Query strings and form bodies for mg_http_get_var
    queries = [
        "a=1&b=two&c=3", "x=%2Fpath%2F&y=spaced+value", "k=v", "name=alice&role=admin"
    ]
    for q in queries:
        parts.append(nul(q))
        # variable names
        parts.append(nul(rng.choice(["a","b","c","x","y","name","role"])) )

    # 6) JSON blobs and JSONPath-like paths
    for _ in range(5):
        parts.append(nul(make_json(rng)))
    paths = ["$.a", "$.b", "$.s", "$.hex", "$.b64", "$.arr[0]", "$", "$.n"]
    for p in paths:
        parts.append(nul(p))

    # 7) Usernames and passwords for auth and Wi-Fi
    for _ in range(4):
        parts.append(nul(rng.choice(USERNAMES)))
        parts.append(nul(rng.choice(PASSWORDS)))
    for _ in range(3):
        parts.append(nul(rng.choice(SSID_SAMPLES)))
        parts.append(nul(rng.choice(PASS_SAMPLES)))

    # 8) Hex/Base64 content for json helpers and %M printers
    for h in HEX_SAMPLES:
        parts.append(nul(h))
    for b in B64_SAMPLES:
        parts.append(nul(b))

    # 9) Cookie header values
    for _ in range(3):
        parts.append(nul(make_cookie(rng)))

    # 10) Filenames and directories for file APIs and serve_dir
    for f in FILENAME_SAMPLES:
        parts.append(nul(f))
    for d in DIR_SAMPLES:
        parts.append(nul(d))

    # 11) Misc short random strings to increase variety
    for _ in range(10):
        parts.append(nul(rand_ascii(rng, 0, 24)))

    blob = b"".join(parts)
    return blob[:MAX_TOTAL]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return assemble_strings(rng)
